from typing import List

def computeParameterValue(sources: List[List[str]]) -> List[str]:
    final = {}  # dict 保持键第一次插入的顺序，覆盖赋值不会改变位置
    for src in sources:              # 优先级从低到高
        for item in src:
            key, value = item.split(":", 1)
            final[key] = value
    return list(final.values())
